const G=9.8,N=60,BR=1.4,TG=[30,45,18];
function shot(a,v){const r=a*Math.PI/180,vx=v*Math.cos(r),vy=v*Math.sin(r),T=2*vy/G;return{vx,vy,T,R:vx*T,H:vy*vy/(2*G)};}
function pos(s,k){const t=s.T*k/N;return[s.vx*t,Math.max(0,s.vy*t-G*t*t/2)+BR,0];}
function pts(c,k){const s=shot(c.a,c.v),p=[];for(let i=0;i<=Math.max(1,k);i++)p.push(pos(s,i));return p;}
export function initialState(){return{ti:0,hits:0,shots:0,fly:false,k:0,cur:null,prev:null,res:null,msg:'Target at 30 m. Set angle and speed, then Launch.'};}
export function reduce({state,event,inputs}){const s=state;
if(event.type==='action'&&event.action==='launch'){if(s.fly||s.hits>=3||s.shots>=10)return s;return{...s,shots:s.shots+1,fly:true,k:0,prev:s.cur,cur:{a:inputs.angle,v:inputs.speed},res:null,msg:'In flight...'};}
if(event.type==='step'&&s.fly){const k=s.k+1;if(k<N)return{...s,k};const sh=shot(s.cur.a,s.cur.v),d=sh.R-TG[s.ti],hit=Math.abs(d)<=1.5,hits=s.hits+(hit?1:0),ti=hit?Math.min(s.ti+1,2):s.ti;let msg;
if(hits>=3)msg='All 3 targets hit in '+s.shots+' launches. You win!';else if(s.shots>=10)msg='Out of launches: '+hits+' of 3 targets hit.';else if(hit)msg='Hit! Next target at '+TG[ti]+' m.';else msg='Missed: '+Math.abs(d).toFixed(1)+' m '+(d<0?'short':'long')+'. '+(10-s.shots)+' launches left.';
return{...s,k:N,fly:false,hits,ti,res:{R:sh.R,miss:Math.abs(d),side:hit?'hit':(d<0?'short':'long'),T:sh.T,H:sh.H},msg};}
return s;}
export function evaluate({inputs,state}){const s=state,th=(inputs.angle-90)*Math.PI/180,nodes={};
nodes.pivot={quaternion:[0,0,Math.sin(th/2),Math.cos(th/2)]};
nodes.target={position:[TG[s.ti],0,0]};
if(s.cur){const p=pts(s.cur,s.k);nodes.ballN={position:p[p.length-1]};nodes.trailN={visible:true,points:p};}else{nodes.ballN={position:[0,BR,0]};nodes.trailN={visible:false};}
if(s.prev)nodes.ghostN={visible:true,points:pts(s.prev,N)};else nodes.ghostN={visible:false};
const readouts={used:s.shots,hitsR:s.hits};if(s.res){readouts.dist=s.res.R;readouts.miss=s.res.miss;readouts.side=s.res.side;readouts.ft=s.res.T;readouts.peak=s.res.H;}
const status=s.hits>=3?'won':(s.shots>=10&&!s.fly?'lost':'playing');
return{nodes,readouts,goal:{status,message:s.msg}};}
